// Replace with your real leads (Google Sheets, CRM, CSV...).
return [
  { json: { company: 'BENITEZ, MICHAEL', state: 'FL', license_number: 'CGC1522906' } },
  { json: { company: 'SMITH', state: 'CA', license_number: '' } },
  { json: { company: 'ACME BUILDERS', state: 'ND', license_number: '' } },
];

// state -> { actor, field }
// `field` matters: these actors do NOT share one input name.
const ACTORS = {
  AL: { actor: 'scrapebench~alabama-contractor-license-lookup',        field: 'query' },
  AR: { actor: 'scrapebench~arkansas-contractor-license-lookup',       field: 'query' },
  CA: { actor: 'scrapebench~california-contractor-license-lookup',     field: 'query' },
  CT: { actor: 'scrapebench~multistate-contractor-license-lookup',     field: 'query', extra: { states: ['CT'] } },
  FL: { actor: 'scrapebench~florida-contractor-license-lookup',        field: 'query' },
  MA: { actor: 'scrapebench~massachusetts-construction-license-lookup', field: 'query' },
  MI: { actor: 'scrapebench~michigan-contractor-license-lookup',       field: 'query' },
  MN: { actor: 'scrapebench~minnesota-contractor-license-lookup',      field: 'query' },
  NC: { actor: 'scrapebench~north-carolina-contractor-license-lookup', field: 'query' },
  NM: { actor: 'scrapebench~new-mexico-contractor-license-lookup',     field: 'businessName' },
  NV: { actor: 'scrapebench~nevada-contractor-license-lookup',         field: 'query' },
  OR: { actor: 'scrapebench~oregon-contractor-license-lookup',         field: 'query' },
  SC: { actor: 'scrapebench~south-carolina-contractor-license-lookup', field: 'lastName' },
  TN: { actor: 'scrapebench~tennessee-contractor-license-lookup',      field: 'query' },
  TX: { actor: 'scrapebench~texas-contractor-license-lookup',          field: 'query' },
  VA: { actor: 'scrapebench~virginia-contractor-license-lookup',       field: 'nameFilter' },
  WA: { actor: 'scrapebench~washington-contractor-license-lookup',     field: 'query' },
};

return $input.all().map((item) => {
  const lead = item.json;
  const state = String(lead.state || '').trim().toUpperCase();
  const cfg = ACTORS[state];

  if (!cfg) {
    // Not covered. Pass it through labelled - never drop it, never call it unlicensed.
    return { json: { ...lead, covered: false, verification_status: 'unverifiable - state not covered' } };
  }

  // Prefer an exact licence number when the lead has one; otherwise search the name.
  const term = String(lead.license_number || '').trim() || String(lead.company || '').trim();
  const input = { [cfg.field]: term, maxResults: 5, ...(cfg.extra || {}) };

  return { json: { ...lead, covered: true, actorId: cfg.actor, actorInput: JSON.stringify(input) } };
});

// Pair each returned licence back to the lead that asked for it, then judge it.
//
// Matching is deliberately conservative: exact licence number if we had one, otherwise a
// normalised name comparison. A near-miss is reported as `review`, never as a pass.
const norm = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

const leads = $('Route by state').all().map((i) => i.json).filter((l) => l.covered);
const rows = $input.all().map((i) => i.json);

const out = [];
for (const lead of leads) {
  const wanted = String(lead.license_number || '').trim();
  const hits = rows.filter((r) => {
    if (wanted) return String(r.license_number || '').trim().toUpperCase() === wanted.toUpperCase();
    const a = norm(lead.company);
    const b = norm(r.business_name || r.company_name || r.person_name);
    return a && b && (a === b || b.includes(a) || a.includes(b));
  });

  if (!hits.length) {
    // NOT the same as "unlicensed" - say exactly what happened.
    out.push({ json: { ...lead, verification_status: 'not-found', note: 'No match at the state portal for this name.' } });
    continue;
  }

  const hit = hits[0];
  const status = String(hit.status || '').toLowerCase();
  const active = status.includes('active') || status.includes('current');
  const exactName = !wanted && norm(lead.company) === norm(hit.business_name || hit.company_name || hit.person_name);

  let verdict;
  if (!active) verdict = 'verified-expired';
  else if (wanted || exactName) verdict = 'verified-active';
  else verdict = 'review'; // active licence, but the name only partially matched

  out.push({ json: {
    ...lead,
    verification_status: verdict,
    license_number: hit.license_number ?? lead.license_number ?? null,
    license_status: hit.status ?? null,
    license_expiry: hit.expiration_date ?? null,
    matched_name: hit.business_name ?? hit.person_name ?? null,
    source_url: hit.source_url ?? null,
  } });
}
return out;
